function validate([items]) {
  if (!Array.isArray(items) || items.length < 1 || items.length > 1000) return 'items needs 1 to 1000 entries.';
  const counts = new Map();
  for (const item of items) {
    if (!Array.isArray(item) || item.length !== 2) return 'Each item is a pair [ID, score].';
    const [id, score] = item;
    if (!Number.isInteger(id) || id < 1 || id > 1000) return 'Each ID is an integer between 1 and 1000.';
    if (!Number.isInteger(score) || score < 0 || score > 100) return 'Each score is an integer between 0 and 100.';
    counts.set(id, (counts.get(id) ?? 0) + 1);
  }
  for (const [id, count] of counts) if (count < 5) return 'Student ' + id + ' needs at least five scores.';
  return null;
}

