function highFive(items) {
  const scores = {};
  for (const [id, score] of items) (scores[id] ??= []).push(score);
  return Object.keys(scores).map(Number).sort((a, b) => a - b).map(id => {
    const best = scores[id].slice().sort((a, b) => b - a).slice(0, 5);
    let sum = 0;
    for (const s of best) sum += s;
    return [id, (sum - (sum % 5)) / 5];
  });
}

