function generate(rand, size) {
  const large = size === 'large';
  // At most 139 students with at most 7 scores each keeps items within 1000.
  const students = large ? 100 + Math.floor(rand() * 40) : 1 + Math.floor(rand() * 3);
  const maxId = large ? 1000 : 9;
  const ids = new Set();
  while (ids.size < students) ids.add(1 + Math.floor(rand() * maxId));
  const items = [];
  for (const id of ids) {
    const count = 5 + Math.floor(rand() * (large ? 3 : 4));
    const low = Math.floor(rand() * 90);
    const high = rand() < 0.3 ? low + Math.floor(rand() * 4) : 100;
    for (let k = 0; k < count; k++) items.push([id, low + Math.floor(rand() * (high - low + 1))]);
  }
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return [items];
}
